  : public Checker<
        check::BeginFunction,
        check::Bind,
        check::PostCall,
        check::BranchCondition> {
   mutable std::unique_ptr<BugType> BT;

public:
  SAGenTestChecker()
      : BT(new BugType(this, "Resource leak in loop iteration (net_device)",
                       "Memory Management")) {}

  void checkBeginFunction(CheckerContext &C) const;
  void checkBind(SVal Loc, SVal Val, const Stmt *StoreE, CheckerContext &C) const;
  void checkPostCall(const CallEvent &Call, CheckerContext &C) const;
  void checkBranchCondition(const Stmt *Condition, CheckerContext &C) const;

private:
  // Helpers
  static bool isAllocNetdevCall(const Expr *E, CheckerContext &C);
  static bool isExitLikeLabel(const LabelDecl *LD);
  static const Stmt* findEnclosingLoop(const Stmt *S, CheckerContext &C);

  static const MemRegion* canonicalizeRegion(ProgramStateRef State,
                                             const MemRegion *R) {
    if (!R) return nullptr;
    R = R->getBaseRegion();
    // Follow aliases a few steps to reach the original source.
    for (int i = 0; i < 8 && R; ++i) {
      if (const MemRegion *const *R2 = State->get<PtrAliasMap>(R))
        R = (*R2)->getBaseRegion();
      else
        break;
    }
    return R;
  }

  static bool isNullTestOfRegion(const Stmt *Condition,
                                 ProgramStateRef State,
                                 const MemRegion *TargetR,
                                 CheckerContext &C) {
    const auto *Cond = dyn_cast_or_null<Expr>(Condition);
    if (!Cond || !TargetR)
      return false;
    Cond = Cond->IgnoreParenImpCasts();
    const Expr *TestedExpr = nullptr;
    if (const auto *Not = dyn_cast<UnaryOperator>(Cond)) {
      if (Not->getOpcode() != UO_LNot)
        return false;
      TestedExpr = Not->getSubExpr();
    } else if (const auto *Cmp = dyn_cast<BinaryOperator>(Cond)) {
      if (Cmp->getOpcode() != BO_EQ ||
          (!Cmp->getLHS()->isNullPointerConstant(C.getASTContext(), Expr::NPC_ValueDependentIsNotNull) &&
           !Cmp->getRHS()->isNullPointerConstant(C.getASTContext(), Expr::NPC_ValueDependentIsNotNull)))
        return false;
      TestedExpr = Cmp->getLHS()->isNullPointerConstant(
                       C.getASTContext(), Expr::NPC_ValueDependentIsNotNull)
                       ? Cmp->getRHS()
                       : Cmp->getLHS();
    } else {
      return false;
    }
    const MemRegion *TestedR = getMemRegionFromExpr(TestedExpr, C);
    return TestedR && canonicalizeRegion(State, TestedR) ==
                          canonicalizeRegion(State, TargetR);
  }

  static bool thenContainsFreeOfRegion(const Stmt *Then, ProgramStateRef State,
                                       const MemRegion *TargetR,
                                       CheckerContext &C) {
    if (!Then || !TargetR)
      return false;

    const MemRegion *CanonTarget = canonicalizeRegion(State, TargetR);
    if (!CanonTarget)
      return false;

    CallCollectorVisitor V;
    V.TraverseStmt(const_cast<Stmt *>(Then));
    for (const CallExpr *CE : V.Calls) {
      if (!CE) continue;
      if (!ExprHasName(CE, "free_netdev", C))
        continue;
      if (CE->getNumArgs() < 1)
        continue;
      const Expr *Arg0 = CE->getArg(0);
      if (!Arg0) continue;
      const MemRegion *ArgR = getMemRegionFromExpr(Arg0, C);
      if (!ArgR) continue;
      ArgR = ArgR->getBaseRegion();
      ArgR = canonicalizeRegion(State, ArgR);
      if (ArgR && ArgR == CanonTarget)
        return true;
    }
    return false;
  }

